 document.querySelectorAll('[data-ho-fund]').forEach(b=>{const on=hoMode&&overlapSelection.has(b.dataset.hoFund);b.classList.toggle('ho-selected',on);b.classList.toggle('ho-selectable',hoMode);if(hoMode)b.setAttribute('aria-pressed',String(on));else b.removeAttribute('aria-pressed')});
