function holdingDayChange(h,c){
 const end=S.pxd?.[h.name],start=c?.since;
 if(!c||!Number.isFinite(c.abs)||!Number.isFinite(c.pct)||!end||!start)return "<div class='ur' style='font-size:12px'><span class='mut'>1D change</span><span class='mut'>N/A</span></div>";
 const days=(Date.parse(end)-Date.parse(start))/86400000;
 const label=days===1?'1D change':'Price change';
 const sign=c.abs>0?'+':c.abs<0?'−':'',arrow=c.abs>0?'▲':c.abs<0?'▼':'—';
 const amount='₹'+Math.abs(c.abs).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
 return `<div style='display:flex;justify-content:space-between;align-items:center;gap:8px;padding:8px 0;border-bottom:1px solid rgba(127,127,127,.15)'><div style='display:grid;gap:2px'><small class='mut'>${label}</small><small class='mut' style='font-size:10px'>${esc(fd(start))} → ${esc(fd(end))}</small></div><strong class='${cls(c.abs)}' style='font-size:13px;text-align:right;font-variant-numeric:tabular-nums'>${arrow} ${sign}${amount} (${sign}${Math.abs(c.pct).toFixed(2)}%)</strong></div>`;
}

function mutualFundHoldingRow(h,c,weight){
 const full=v=>'₹'+Math.round(Math.abs(v)).toLocaleString('en-IN');
 const end=S.pxd?.[h.name],history=(typeof NH!=='undefined'?NH[h.name]?.d:[])||[];c=holdingInvestorChange(h,holdingPeriod);const start=c?.since,days=(Date.parse(end)-Date.parse(start))/86400000;
 const valid=c&&Number.isFinite(c.abs)&&days>0;
 const reason=!end?'NAV date missing':!history.length?'NAV history unavailable':'Comparable NAV unavailable';
 const move=valid?`<span class='mut' title='Cash-flow-adjusted gain and Modified Dietz return · ${fd(start)} – ${fd(end)}'>${holdingPeriod}</span> <b class='${cls(c.abs)}' style='white-space:nowrap'>${holdingChangeAmount(c.abs)} · ${Number.isFinite(c.pct)?(c.pct>0?'▲':c.pct<0?'▼':'—')+Math.abs(c.pct).toFixed(2)+'%':'N/A'}</b>`:`<span class='mut' title='${reason}'>${holdingPeriod} · ${NHBUSY?'Loading…':'N/A'}</span>`;
 return `<button type='button' ${holdingMatches(h.name,holdingQuery)?'':'hidden'} class='hc mf-holding-row' data-ho-fund='${esc(h.name)}' data-h='${esc(h.name)}' style='${holdingMatches(h.name,holdingQuery)?'display:block;':'display:none;'}text-align:left;width:100%;padding:12px 10px'><div class='mf-holding-head' style='display:flex;align-items:center;gap:8px'><span class='ho-check' aria-hidden='true'></span><span style='display:flex;flex:none;width:36px;height:36px;border-radius:50%;overflow:hidden;align-items:center;justify-content:center'>${av(h.name)}</span><div style='flex:1;min-width:0'><b class='mf-holding-name' title='${esc(h.name)}' style='display:block;font-size:14px;line-height:1.25'>${esc(h.name)}</b><div style='font-size:12px;line-height:1.5;margin-top:2px'>${move}</div></div></div><div class='mf-holding-values' style='display:grid;font-variant-numeric:tabular-nums'><div style='min-width:0'><small class='mut' style='font-size:11px'>Invested</small><strong style='display:block;margin-top:3px'>${full(h.cost)}</strong></div><div style='min-width:0;text-align:center'><small class='mut' style='font-size:11px'>Current</small><strong style='display:block;margin-top:3px'>${full(h.value)}</strong></div><div style='min-width:0;text-align:right'><small style='font-size:11px'>Gain <b class='${cls(h.pl)}' style='white-space:nowrap'>(${h.pl>0?'▲':h.pl<0?'▼':'—'}${Math.abs(h.plp).toFixed(2)}%)</b></small><strong class='${cls(h.pl)}' style='display:block;margin-top:3px'>${h.pl>0?'+':h.pl<0?'−':''}${full(h.pl)}</strong></div></div>${holdingCompact?'':`<div style='display:flex;justify-content:space-between;margin-top:7px;font-size:10px' class='mut'><span>XIRR ${pc(h.xirr)}</span><span>${weight.toFixed(2)}% of portfolio</span></div>`}</button>`;
}

function holdingPeriodFilter(){return "<div style='display:flex;align-items:center;justify-content:space-between;gap:8px;margin:6px 2px;padding:4px 0'><label for='holdingPeriod' class='mut' style='font-size:12px;white-space:nowrap;flex:1;min-width:0'>MF investment return period</label><select id='holdingPeriod' style='width:88px;max-width:88px;min-width:0;flex:0 0 88px;font-size:13px;min-height:34px;height:34px;padding:4px 8px;margin:0'>"+holdingPeriods.map(p=>"<option "+(p===holdingPeriod?"selected":"")+">"+p+"</option>").join("")+"</select></div>"}
document.addEventListener('change',e=>{if(e.target.id==='holdingPeriod'&&holdingPeriods.includes(e.target.value)){holdingPeriod=e.target.value;render()}});
function holdingPeriodChange(history,end,price,units,period){
 if(!/^\d{4}-\d{2}-\d{2}$/.test(end||'')||!Number.isFinite(price)||price<=0||!Number.isFinite(units)||!holdingPeriods.includes(period))return null;
 const rows=history.filter(([d,p])=>d<=end&&Number.isFinite(p)&&p>0).sort((a,b)=>b[0].localeCompare(a[0]));
 const same=rows.find(([d])=>d===end);
 if(same&&Math.abs(same[1]-price)>0.000051)return null;
 let prior;
 if(period==='1D'){prior=rows.find(([d])=>d<end);if(prior&&Date.parse(end)-Date.parse(prior[0])>7*86400000)return null;}
 else{
 const target=new Date(end+'T00:00:00Z'),n=parseInt(period),unit=period.slice(-1);
 if(unit==='W')target.setUTCDate(target.getUTCDate()-7*n);
 else{const day=target.getUTCDate();target.setUTCDate(1);target.setUTCMonth(target.getUTCMonth()-n*(unit==='Y'?12:1));target.setUTCDate(Math.min(day,new Date(Date.UTC(target.getUTCFullYear(),target.getUTCMonth()+1,0)).getUTCDate()))}
 const date=target.toISOString().slice(0,10);prior=rows.find(([d])=>d<=date);
 if(prior&&Date.parse(date)-Date.parse(prior[0])>7*86400000)return null;
 }
 return prior?{abs:(price-prior[1])*units,pct:(price/prior[1]-1)*100,since:prior[0]}:null;
}

function holdingInvestorChange(h,period){
 const end=S.pxd?.[h.name],history=h.type==='mf'?(NH[h.name]?.d||[]):(PWH[h.name]||[]);
 if(!/^\d{4}-\d{2}-\d{2}$/.test(end||'')||!Number.isFinite(h.price)||h.price<=0||!Number.isFinite(h.units)||!holdingPeriods.includes(period))return null;
 const tx=S.tx.filter(t=>t.name===h.name&&t.type===h.type).sort((a,b)=>a.date.localeCompare(b.date));
 if(!tx.length||tx.some(t=>t.date>end))return null;
 const nav=holdingPeriodChange(history,end,h.price,h.units,period);
 const target=new Date(end+'T00:00:00Z'),n=parseInt(period),unit=period.slice(-1);
 if(period==='1D')target.setUTCDate(target.getUTCDate()-1);
 else if(unit==='W')target.setUTCDate(target.getUTCDate()-7*n);
 else{const d=target.getUTCDate();target.setUTCDate(1);target.setUTCMonth(target.getUTCMonth()-n*(unit==='Y'?12:1));target.setUTCDate(Math.min(d,new Date(Date.UTC(target.getUTCFullYear(),target.getUTCMonth()+1,0)).getUTCDate()))}
 const since=nav?.since||target.toISOString().slice(0,10);
 if(!nav&&tx[0].date<=since)return null;
 const days=(Date.parse(end)-Date.parse(since))/86400000;if(days<=0)return null;
 let openingUnits=0,units=0,net=0,weighted=0;
 for(const t of tx){if(!['buy','sell'].includes(t.side)||!Number.isFinite(t.units)||!Number.isFinite(t.price)||t.units<=0||t.price<=0)return null;const sign=t.side==='buy'?1:-1;units+=sign*t.units;if(units< -1e-6)return null;if(t.date<=since){openingUnits+=sign*t.units;continue}const flow=sign*t.units*t.price+(t.fee||0);net+=flow;weighted+=flow*(Date.parse(end)-Date.parse(t.date))/86400000/days;}
 if(Math.abs(units-h.units)>Math.max(1e-6,Math.abs(h.units)*1e-8))return null;
 const openingPrice=history.find(([d,p])=>d===since&&Number.isFinite(p)&&p>0)?.[1];
 if(openingUnits>1e-8&&(!nav||!openingPrice))return null;
 const opening=openingUnits*(openingPrice||0),abs=h.units*h.price-opening-net,capital=opening+weighted;
 return {abs,pct:capital>0?abs/capital*100:null,since,capital};
}
function holdingChangeAmount(v){return (v<0?'−':v>0?'+':'')+'₹'+Math.abs(v).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2})}
function dailyHoldingAggregate(targets){
 const changes=targets.map(h=>({h,c:holdingInvestorChange(h,'1D')}));
 const valid=changes.filter(x=>x.c&&Number.isFinite(x.c.abs)&&Number.isFinite(x.c.capital));
 const aligned=valid.length>0&&new Set(valid.map(x=>x.c.since)).size===1&&new Set(valid.map(x=>S.pxd?.[x.h.name])).size===1;
 return {gain:valid.reduce((sum,x)=>sum+x.c.abs,0),capital:valid.reduce((sum,x)=>sum+x.c.capital,0),count:valid.length,total:targets.length,aligned,start:valid[0]?.c.since,end:valid[0]?S.pxd?.[valid[0].h.name]:null};
}
function dailyHoldingMarkup(targets,showDates=false){
 const r=dailyHoldingAggregate(targets);
 if(!r.count)return '<span>1-day market change · History unavailable</span>';
 const direction=r.gain>0?'up':r.gain<0?'down':'flat';
 const note=r.aligned?'Aligned valuation dates':'Latest available holding changes; NAV/price dates differ. Percentage uses combined opening capital, not a common-date portfolio return.';
 return `<span class="day-change-label" title="${esc(note)}">1-day market change</span><strong class="day-change-${direction}" title="${esc(note)}">${r.gain>0?'▲ ':r.gain<0?'▼ ':''}${holdingChangeAmount(r.gain)}${r.capital>0?' ('+pc(r.gain/r.capital*100)+')':''}</strong>${r.count<r.total?`<small>${r.count}/${r.total} holdings</small>`:''}${showDates&&r.aligned?`<small>${fd(r.start)} – ${fd(r.end)}</small>`:''}`;
}
function holdingSummaryHero(C,L,tot,cost,gain){
 const all=flt==='all',label=all?'PORTFOLIO VALUE':flt==='mf'?'MUTUAL FUNDS':'STOCKS';
 const daily=dailyHoldingMarkup(L,false);
 const filteredLedger=all?[]:fifoLedger(S.tx.filter(t=>t?.type===flt),today(),(S.corporateActions??[]).filter(a=>a.type===flt));
 const rate=all?C.xirr:filteredLedger.some(h=>h.unmatched>1e-9||h.rejectedActions?.length||h.rejectedTransactions?.length)?null:xirr(filteredLedger.flatMap(h=>h.flows).concat([[today(),tot]]));
 const warning=L.some(h=>!h.valuation||h.valuation.estimated||!h.valuation.date||['missing','stale'].includes(h.valuation.status));
 return `<section class='hero overview-hero holdings-summary ho-redesign'><div class='ho-hero-label'><span class='lab'>${label}</span><small>${L.length} holdings</small></div><h1>${cr(tot)}</h1><div class='overview-day-change'>${daily}</div>${warning?`<p class='sub'>⚠ Valuation data warning</p>`:''}<div class='overview-kpis overview-kpis-compact'><div><small>Invested</small><strong>${cr(cost)}</strong></div><div><small class='overview-gain-label'>Gain <span class='${cls(gain)}'>(${pc(cost>0?gain/cost*100:null)})</span></small><strong class='${cls(gain)}'>${cr(gain)}</strong></div><div><small>XIRR (p.a.)</small><strong class='${Number.isFinite(rate)?cls(rate):""}'>${Number.isFinite(rate)?pc(rate):'N/A'}</strong></div></div><div class='chips holdings-actions ho-integrated-actions'><button data-hist=''><span aria-hidden='true'>⇅</span>Transactions</button>${elssData().length?`<button data-a='elss'><span aria-hidden='true'>♙</span>ELSS lock-in</button>`:''}${flt!=='stock'?holdingOverlap(C):''}</div></section><div id='ho-selection-dock' class='ho-selection-dock'></div>`;

}

function exposureDashboard(p,count){
 const concentration=n=>p.exposure.slice(0,n).reduce((sum,x)=>sum+x.weight,0);
 const max=p.exposure[0]?.weight||1,scale=concentration(20)||1;
 return `<section class='ho-exposure'><div class='card pad ho-exp-summary'><div class='ho-exp-heading'><strong>Combined underlying exposure</strong><span>${count} funds</span></div><small class='mut'>% of total selected fund value</small><div class='ho-exp-concentration'>${[5,10,20].map(n=>`<div><span>Top ${n}</span><div class='ho-exp-track'><i style='width:${Math.min(100,100*concentration(n)/scale)}%'></i></div><b>${concentration(n).toFixed(2)}%</b></div>`).join('')}</div><div class='ho-exp-quality'><span class='mut'>${p.missing.length?'⚠':'✓'} ${p.total?(100*p.covered/p.total).toFixed(1):'0'}% coverage · ${p.missing.length} missing/stale · ${p.dates.map(esc).join(', ')||'No dates'}</span><details><summary aria-label='Exposure methodology'>i</summary><p>Exposure percentages use total selected fund value. Concentration bars are relative to Top 20; stock bars are relative to the largest disclosed exposure. Mixed disclosure dates may affect comparisons.</p></details></div></div><div class='ho-exp-controls ho-inline-v141' style='display:flex!important;align-items:center;gap:6px;flex-wrap:nowrap!important;margin:10px 0'><label class='ho-exp-searchbox' style='display:flex!important;flex:1.25 1 0;min-width:0;margin:0;align-items:center'><svg aria-hidden='true' width='16' height='16' viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2'><circle cx='10.5' cy='10.5' r='6.5'/><path d='m16 16 5 5'/></svg><input type='search' placeholder='Search stocks' aria-label='Search stocks' data-exp-search style='width:0!important;flex:1;min-width:0'></label><label class='ho-exp-selectbox'><select aria-label='Filter stocks' data-exp-filter><option value='all'>All stocks</option><option value='shared'>Overlapping</option><option value='unique'>Single fund</option></select><svg aria-hidden='true' viewBox='0 0 16 16' width='12' height='12' fill='currentColor'><path d='M3 6h10l-5 5z'/></svg></label><label class='ho-exp-selectbox'><select aria-label='Sort exposure' data-exp-sort><option value='weight'>Exposure %</option><option value='value'>Exposure amount</option><option value='funds'>Fund count</option></select><svg aria-hidden='true' viewBox='0 0 16 16' width='12' height='12' fill='currentColor'><path d='M3 6h10l-5 5z'/></svg></label></div><div class='ho-exp-list'>${p.exposure.map(x=>`<details class='ho-exp-row' data-exp-name='${esc(x.name.toLowerCase())}' data-exp-funds='${x.funds}' data-exp-value='${x.value}' data-exp-weight='${x.weight}'><summary><div class='ho-exp-main'><div><strong>${esc(x.name)}</strong><small class='${x.funds>1?'g':'mut'}'>${x.funds} ${x.funds===1?'fund':'funds · Overlapping'}</small></div><div class='ho-exp-number'><b>${cr(x.value)}</b><small>${x.weight.toFixed(2)}%</small></div></div><div class='ho-exp-track'><i style='width:${Math.min(100,100*x.weight/max)}%'></i></div></summary><div class='ho-exp-details'><small class='mut'>Estimated fund-wise exposure</small>${x.contributions.map(c=>`<div><span>${esc(c.name)}<small class='mut'>${c.weight.toFixed(2)}% of fund NAV · ${esc(c.date)}</small></span><b>${cr(c.value)}</b></div>`).join('')}</div></details>`).join('')}</div><p class='mut' data-exp-empty hidden>No matching stocks.</p></section>`;
}
function filterExposure(root){
 const q=root.querySelector('[data-exp-search]').value.trim().toLowerCase(),f=root.querySelector('[data-exp-filter]').value,k=root.querySelector('[data-exp-sort]').value,list=root.querySelector('.ho-exp-list');
 const rows=[...list.children].sort((a,b)=>Number(b.dataset['exp'+k[0].toUpperCase()+k.slice(1)])-Number(a.dataset['exp'+k[0].toUpperCase()+k.slice(1)]));let count=0;
 for(const row of rows){const n=Number(row.dataset.expFunds);row.hidden=!(row.dataset.expName.includes(q)&&(f==='all'||(f==='shared'?n>1:n===1)));if(!row.hidden)count++;list.append(row)}
 root.querySelector('[data-exp-empty]').hidden=count!==0;
}
document.addEventListener('input',e=>{if(e.target.matches('[data-exp-search]'))filterExposure(e.target.closest('.ho-exposure'))});
document.addEventListener('change',e=>{if(e.target.matches('[data-exp-filter],[data-exp-sort]'))filterExposure(e.target.closest('.ho-exposure'))});

document.addEventListener('click',e=>{const b=e.target.closest('[data-ho-quick]');if(!b)return;const k=b.dataset.hoQuick;if(lsort===k)holdingAscending=!holdingAscending;else{lsort=k;holdingAscending=false}saveHoldingPreferences();render()});

